def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [[0] * w for _ in range(h)]
    blocks = []

    for r in range(h - 1):
        for c in range(w - 1):
            if all(grid[rr][cc] == 2
                   for rr in (r, r + 1) for cc in (c, c + 1)):
                blocks.append((r, c))
                for rr in (r, r + 1):
                    for cc in (c, c + 1):
                        out[rr][cc] = 2

    # Each marker moves clockwise to the next corner and extends diagonally outward.
    for r, c in blocks:
        corners = [
            (r - 1, c - 1),  # top-left
            (r - 1, c + 2),  # top-right
            (r + 2, c + 2),  # bottom-right
            (r + 2, c - 1),  # bottom-left
        ]
        colors = [grid[rr][cc] if 0 <= rr < h and 0 <= cc < w else 0
                  for rr, cc in corners]

        # TL -> TR, TR -> BR, BR -> BL, BL -> TL
        destinations = [corners[1], corners[2], corners[3], corners[0]]
        directions = [(-1, 1), (1, 1), (1, -1), (-1, -1)]

        for color, (rr, cc), (dr, dc) in zip(colors, destinations, directions):
            if color == 0 or not (0 <= rr < h and 0 <= cc < w):
                continue
            while 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = color
                rr += dr
                cc += dc

    return out
